+def _write_json_atomic(target: Path, data: dict) -> None:
+    """以 0644 权限将配置字典原子写回目标 JSON 文件。"""
+    tmp_file = target.with_name(target.name + '.tmp')
+    tmp_file.write_text(json.dumps(data, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
+    tmp_file.chmod(0o644)
+    tmp_file.replace(target)
+    target.chmod(0o644)
+
+
+def _read_default_language(default_settings: Path) -> str:
+    """读取只读模板 settings.json 中的默认语言代码；缺失或异常时返回空串。"""
+    if not default_settings.is_file():
+        return ''
+    try:
+        doc = json.loads(default_settings.read_text(encoding='utf-8'))
+    except (OSError, ValueError):
+        return ''
+    lang = doc.get('language', '') if isinstance(doc, dict) else ''
+    return lang if isinstance(lang, str) else ''
+
+
+def migrate_default_language_once(data: dict, default_lang: str) -> bool:
+    """对尚未标记迁移的存量英文或空语言配置执行一次性默认中文迁移。
+
+    参数:
+        data: 已加载的可写配置字典，原地更新语言与一次性迁移标记。
+        default_lang: 只读包内 `config/settings.json` 声明的默认语言代码。
+    返回:
+        bool: 若本次写入了迁移标记或更新了语言返回 True，无需修改返回 False。
+    """
+    if not isinstance(data, dict) or default_lang != 'zh':
+        return False
+    if 'c308l_default_lang_migrated' in data:
+        return False
+    # 仅在首次升级且原语言为空或存量默认英文时切为中文，后续用户手动切回英文不再覆盖。
+    cur_lang = data.get('language', '')
+    if cur_lang in ('', 'en', None):
+        data['language'] = 'zh'
+    data['c308l_default_lang_migrated'] = 1
+    return True
+
+
+def _panel_backup_candidates(panel_config: Path) -> list:
