+    // 仅拦截在途活跃任务；MC 待恢复模式 (!st.active && st.maintenance) 必须允许扫描恢复包。
+    if (st.active) return AisocOtaGateVerdict::BACKEND_BUSY;
+    return AisocOtaGateVerdict::ALLOW;
