211	void OtaLocalOverlay::sync_from_backend() {
212	#ifdef HELIX_ENABLE_AISOC
213	    auto* conn = helix::aisoc::active_aisoc_connection();
214	    if (!conn || !subjects_initialized_) return;
215	    const auto st = conn->ota_status();
216	    const auto snap = conn->snapshot();
217	    // RPC 刚受理但尚未收到新 task 首个 DDS 事件（event_id==0）时跳过旧残影覆盖，等待真实 DDS 状态。
218	    if (!st.task_id.empty() && st.event_id == 0U && st.last_rpc_code == 0) return;
219	    // 同时要求 scan_state == READY、valid 与有效 SHA-256，防止未重检节点残留旧摘要。
220	    scanned_mc_sha256_ = helix::aisoc::is_ota_node_pkg_ready(st.mc) ? st.mc.sha256 : std::string();
221	    scanned_th_sha256_ = helix::aisoc::is_ota_node_pkg_ready(st.th) ? st.th.sha256 : std::string();
222	    const std::string phase_str = format_ota_phase(st);
223	    const std::string mc_str = format_ota_pkg("fw_mc.bin", st.mc);
224	    const std::string th_str = format_ota_pkg("fw_th.bin", st.th);
225	    lv_subject_copy_string(&phase_subject_, phase_str.c_str());
226	    lv_subject_copy_string(&mc_pkg_subject_, mc_str.c_str());
227	    lv_subject_copy_string(&th_pkg_subject_, th_str.c_str());
228	    lv_subject_set_int(&progress_subject_, static_cast<int32_t>(st.progress_pct));
229	    if (scan_feedback_pending_) {
230	        const auto fb = helix::aisoc::evaluate_ota_scan_feedback(pending_scan_seq_, st);
231	        if (fb != helix::aisoc::AisocScanFeedback::NONE) {
232	            scan_feedback_pending_ = false;
233	            pending_scan_seq_ = 0U;
234	            ToastSeverity sev = ToastSeverity::WARNING;
235	            if (fb == helix::aisoc::AisocScanFeedback::SUCCESS) sev = ToastSeverity::SUCCESS;
236	            else if (fb == helix::aisoc::AisocScanFeedback::ERROR) sev = ToastSeverity::ERROR;
237	            ToastManager::instance().show(sev, phase_str.c_str(), 2800);
238	        }
239	    }
240	    set_lock_hint(format_ota_lock_text(helix::aisoc::evaluate_ota_lock_state(st, snap)));
241	#endif
242	}
