265	void OtaLocalOverlay::handle_start_upgrade() {
266	#ifdef HELIX_ENABLE_AISOC
267	    auto* conn = helix::aisoc::active_aisoc_connection();
268	    if (!conn) {
269	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
270	        return;
271	    }
272	    const uint8_t mask = static_cast<uint8_t>((select_mc_ ? 1U : 0U) | (select_th_ ? 2U : 0U));
273	    const auto st = conn->ota_status();
274	    const auto snap = conn->snapshot();
275	    const auto verdict = helix::aisoc::check_ota_upgrade_gate(mask, confirmed_safe_, st, snap);
276	    if (verdict == helix::aisoc::AisocOtaGateVerdict::MISSING_SELECTION) {
277	        ToastManager::instance().show(ToastSeverity::WARNING, "请选择升级节点并开启安全前置确认", 2500);
278	        return;
279	    }
280	    if (verdict == helix::aisoc::AisocOtaGateVerdict::BACKEND_BUSY) {
281	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 后台已锁定 (BUSY)", 2000);
282	        return;
283	    }
284	    if (verdict == helix::aisoc::AisocOtaGateVerdict::MC_RECOVERY_ONLY) {
285	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: MC 处于待恢复模式，请取消选择 TH 仅升级 MC", 2800);
286	        return;
287	    }
288	    if (verdict == helix::aisoc::AisocOtaGateVerdict::PACKAGE_NOT_READY) {
289	        ToastManager::instance().show(ToastSeverity::WARNING, "请先扫描固件并确认所选节点固件包校验通过", 2500);
290	        return;
291	    }
292	    if (verdict == helix::aisoc::AisocOtaGateVerdict::DISCONNECTED) {
293	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
294	        return;
295	    }
296	    if (verdict == helix::aisoc::AisocOtaGateVerdict::NODE_OFFLINE) {
297	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 节点离线（请检查板卡连接待恢复 ONLINE 后重试）", 2500);
298	        return;
299	    }
300	    scan_feedback_pending_ = false;
301	    pending_scan_seq_ = 0U;
302	    helix::aisoc::AisocOtaRequest req;
303	    req.operation = 1U;
304	    req.target_mask = mask;
305	    req.confirmed_safe = true;
306	    req.allow_reflash = allow_reflash_;
307	    req.mc_sha256 = ((mask & 1U) != 0U) ? st.mc.sha256 : std::string();
308	    req.th_sha256 = ((mask & 2U) != 0U) ? st.th.sha256 : std::string();
309	    (void)conn->request_ota(req);
310	#endif
311	}
