    93	/** @brief rt 为任务状态；扫描态遍历全部所选包不短路，升级态任一错误立即阻断不进 Boot。 */
    94	static bool prepare_images(fwd_ota_runtime* rt) {
    95	    if (rt == nullptr) return false;
    96	    ota_emit(rt, "PRECHECK", "");
    97	    bool has_sig_err = false;
    98	    bool has_inv_err = false;
    99	    bool has_missing = false;
   100	    for (uint8_t index = 0U; index < 2U; ++index) {
   101	        if ((rt->mask & (1U << index)) == 0U) continue;
   102	        rt->current = index;
   103	        if (ota_load_image(rt, index)) {
   104	            ota_emit(rt, "PACKAGE_VERIFIED", "");
   105	            continue;
   106	        }
   107	        const bool sig_bad = std::strcmp(rt->scan_state[index], "SIGNATURE_INVALID") == 0;
   108	        if (rt->operation != 0U) {
   109	            // 升级执行态任一目标包预检失败立即短路，严禁进入 Boot 或擦写。
   110	            ota_emit(rt, "FAILED", sig_bad ? "PACKAGE_SIGNATURE_INVALID" : "PACKAGE_INVALID_OR_CHANGED");
   111	            return false;
   112	        }
   113	        // 扫描态完整检查请求掩码内的双节点，避免单包缺失短路跳过另一节点摘要计算。
   114	        if (sig_bad) has_sig_err = true;
   115	        else if (std::strcmp(rt->scan_state[index], "MISSING") == 0) has_missing = true;
   116	        else has_inv_err = true;
   117	    }
   118	    if (has_sig_err || has_inv_err || has_missing) {
   119	        const char* err = "PACKAGE_MISSING";
   120	        if (has_sig_err) err = "PACKAGE_SIGNATURE_INVALID";
   121	        else if (has_inv_err) err = "PACKAGE_INVALID_OR_CHANGED";
   122	        ota_emit(rt, "FAILED", err);
   123	        return false;
   124	    }
   125	    return true;
   126	}
