   128	/** @brief rt 为已结束任务；优先报告锁存的通信错误，保留首个故障节点/命令/序号。 */
   129	static const char* task_error(const fwd_ota_runtime* rt) {
   130	    if (rt == nullptr) return "INVALID_TASK";
   131	    switch (rt->communication_error) {
   132	        case AISOC_FWD_ERR_SERIAL_OPEN: return "SERIAL_NOT_READY";
   133	        case AISOC_FWD_ERR_SERIAL_IO: return "SERIAL_IO_ERROR";
   134	        case AISOC_FWD_ERR_TIMEOUT: return "SERIAL_TIMEOUT";
   135	        case AISOC_FWD_ERR_NACK: return "REMOTE_NACK";
   136	        case AISOC_FWD_OK: break;
   137	        default: return "COMMUNICATION_FAILED";
   138	    }
   139	    return rt->error[0] == '\0' ? "UPGRADE_INTERRUPTED" : rt->error;
   140	}
   141	
   142	/** @brief rt 为已受理任务；串行执行，失败冻结并停止后续节点，不自动重刷。 */
   143	static void execute_task(fwd_ota_runtime* rt) {
   144	    if (rt == nullptr || !prepare_images(rt)) return;
   145	    if (rt->operation == 0U) {
   146	        ota_emit(rt, "READY", "");
   147	        return;
   148	    }
   149	    // TH 依赖 MC App 路由，正常始终先 TH；MC 已在 Boot 的恢复由单独 MC 指令执行。
   150	    const uint8_t order[2] = {1U, 0U};
   151	    for (uint8_t index : order) {
   152	        if ((rt->mask & (1U << index)) == 0U) continue;
   153	        rt->current = index;
   154	        if (ota_stopping(rt) || !ota_preflight(rt) || !ota_upgrade_node(rt)) {
   155	            ota_emit(rt, "FAILED", task_error(rt));
   156	            return;
   157	        }
   158	    }
   159	    pthread_mutex_lock(&rt->mutex);
   160	    rt->recovery_pending = false;
   161	    pthread_mutex_unlock(&rt->mutex);
   162	    ota_emit(rt, "SUCCEEDED", "");
   163	}
