   281	aisoc_fwd_status_t fwd_ota_service_start(forward_service_state_t* state) {
   282	    if (state == nullptr) return AISOC_FWD_ERR_NULL_PTR;
   283	    if (runtime.owner != nullptr) return AISOC_FWD_ERR_BUSY;
   284	    auto* rt = &runtime;
   285	    *rt = {};
   286	    if (pthread_mutex_init(&rt->mutex, nullptr) != 0) return AISOC_FWD_ERR_SERIAL_IO;
   287	    if (pthread_cond_init(&rt->wake, nullptr) != 0) {
   288	        pthread_mutex_destroy(&rt->mutex);
   289	        return AISOC_FWD_ERR_SERIAL_IO;
   290	    }
   291	    rt->initialized = true;
   292	    rt->owner = state;
   293	    rt->phase = "IDLE";
   294	    rt->error = "";
   295	    rt->task_id = static_cast<uint64_t>(std::time(nullptr)) * 1000000U;
   296	    rt->image[0] = {mc_image, sizeof(mc_image), 0U, 0U, 0U, false, {0}};
   297	    rt->image[1] = {th_image, sizeof(th_image), 0U, 0U, 0U, false, {0}};
   298	    std::snprintf(rt->scan_state[0], sizeof(rt->scan_state[0]), "UNSCANNED");
   299	    std::snprintf(rt->scan_state[1], sizeof(rt->scan_state[1]), "UNSCANNED");
   300	    state->ota = rt;
   301	    const aisoc_dds_publisher_config_t config = {AISOC_TOPIC_OTA_STATUS, AISOC_DDS_QOS_RELIABLE_TRANSIENT_LOCAL};
   302	    const auto status = aisoc_dds_publisher_create(state->dds_participant, &config, &rt->publisher);
   303	    if (status != AISOC_DDS_OK) {
   304	        fwd_ota_service_stop(state);
   305	        return AISOC_FWD_ERR_DDS_INIT;
   306	    }
   307	    if (pthread_create(&rt->worker, nullptr, worker_main, rt) != 0) {
   308	        fwd_ota_service_stop(state);
   309	        return AISOC_FWD_ERR_SERIAL_IO;
   310	    }
   311	    rt->worker_started = true;
   312	    if (pthread_create(&rt->reporter, nullptr, reporter_main, rt) != 0) {
   313	        fwd_ota_service_stop(state);
   314	        return AISOC_FWD_ERR_SERIAL_IO;
   315	    }
   316	    rt->reporter_started = true;
   317	    ota_emit(rt, "IDLE", "");
   318	    return AISOC_FWD_OK;
   319	}
   320	
   321	void fwd_ota_service_stop(forward_service_state_t* state) {
   322	    if (state == nullptr || state->ota == nullptr) return;
   323	    auto* rt = state->ota;
   324	    pthread_mutex_lock(&rt->mutex);
   325	    rt->stopping = true;
   326	    pthread_cond_broadcast(&rt->wake);
   327	    pthread_mutex_unlock(&rt->mutex);
   328	    if (rt->worker_started) pthread_join(rt->worker, nullptr);
   329	    if (rt->reporter_started) pthread_join(rt->reporter, nullptr);
