342	bool parse_dm_snapshot_json(const std::string& json, AisocSnapshot* out_snap) {
343	    if (out_snap == nullptr || !detail::json_is_valid_object(json)) return false;
344	    std::string sys_st, dev_st;
345	    if (!detail::json_extract_string(json, "system_status", &sys_st)) return false;
346	    if (!detail::json_extract_string(json, "device_state", &dev_st)) return false;
347	    out_snap->system_status = sys_st;
348	    out_snap->device_state = dev_st;
349	    out_snap->maintenance_locked = (sys_st == "MAINTENANCE_HOLD");
350	    // 从权威布尔字段解析本地急停锁与双板确认态，彻底解耦会被板卡故障覆写为 FAULT 的 system_status 字符串。
351	    bool latched = false;
352	    bool confirmed = false;
