354	    const bool has_confirmed = detail::json_extract_bool(json, "estop_confirmed", &confirmed);
355	    out_snap->estop_latched = has_latched && latched;
356	    out_snap->estop_confirmed = out_snap->estop_latched && has_confirmed && confirmed;
