488	void AisocConnection::worker_loop() {
489	    while (true) {
490	        process_pending_estops();
491	        process_pending_ota();
492	        poll_ota_dds();
493	        bool do_refresh = false;
494	        {
495	            std::lock_guard<std::mutex> lock(mutex_);
496	            if (stop_requested_) break;
497	            do_refresh = refresh_requested_;
498	            refresh_requested_ = false;
499	        }
500	        poll_once();
501	        poll_ota_dds();
502	        if (do_refresh) process_pending_estops();
503	        std::unique_lock<std::mutex> lock(mutex_);
504	        if (stop_requested_) break;
505	        uint32_t wait_ms = config_.poll_interval_ms > 0U ? config_.poll_interval_ms : 1000U;
506	        if ((ota_status_.active || pending_reboot_verify_) && wait_ms > 80U) wait_ms = 80U;
507	        cv_.wait_for(lock, std::chrono::milliseconds(wait_ms), [this]() {
508	            return stop_requested_ || refresh_requested_ || !estop_queue_.empty() || !ota_queue_.empty();
509	        });
510	        if (stop_requested_) break;
511	    }
512	}
513	
514	void AisocConnection::process_pending_estops() {
515	    while (true) {
516	        bool engage = true;
517	        EstopCallback cb;
518	        {
519	            std::lock_guard<std::mutex> lock(mutex_);
520	            if (stop_requested_ || estop_queue_.empty()) return;
521	            engage = estop_queue_.front();
522	            estop_queue_.erase(estop_queue_.begin());
523	            cb = estop_cb_;
524	        }
525	        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
526	        const AisocEstopResult res = execute_dm_estop(conn, engage, config_.rpc_timeout_ms);
527	        if (res.outcome == AisocEstopOutcome::DISCONNECTED) close_dbus(&dbus_handle_);
528	        AisocSnapshot updated;
529	        AisocOtaStatus ota_snap;
530	        OtaStatusCallback ota_cb;
531	        {
532	            std::lock_guard<std::mutex> lock(mutex_);
533	            if (res.outcome == AisocEstopOutcome::CONFIRMED) {
534	                snapshot_.estop_latched = engage;
535	                snapshot_.estop_confirmed = engage;
536	            } else if (res.outcome == AisocEstopOutcome::DISCONNECTED) {
537	                snapshot_.estop_latched = false;
538	                snapshot_.estop_confirmed = false;
539	            } else if (engage && res.outcome == AisocEstopOutcome::FAILED) {
540	                snapshot_.estop_confirmed = false;
541	                refresh_requested_ = true;
542	            }
543	            snapshot_.last_estop_outcome = res.outcome;
544	            snapshot_.last_estop_detail = res.detail;
545	            updated = snapshot_;
546	            ota_snap = ota_status_;
547	            ota_cb = ota_cb_;
548	        }
549	        publish_if_changed(updated, true);
550	        if (ota_cb) ota_cb(ota_snap);
551	        if (cb) cb(res);
552	    }
553	}
554	
555	void AisocConnection::process_pending_ota() {
556	    while (true) {
557	        QueuedOtaRequest item;
558	        {
559	            std::lock_guard<std::mutex> lock(mutex_);
560	            if (stop_requested_ || ota_queue_.empty()) return;
561	            item = ota_queue_.front();
562	            ota_queue_.erase(ota_queue_.begin());
563	        }
564	        ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
565	        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
566	        uint64_t task_id = 0U;
567	        const int32_t rc = execute_fwd_ota_command(conn, item.request, config_.rpc_timeout_ms, &task_id);
568	        AisocOtaStatus next;
569	        {
570	            std::lock_guard<std::mutex> lock(mutex_);
571	            next = ota_status_;
572	            next.last_rpc_code = rc;
573	            if (rc == 0) {
574	                tracked_task_id_ = std::to_string(task_id);
575	                tracked_req_seq_ = item.req_seq;
576	                pending_reboot_verify_ = false;
577	                next.task_id = tracked_task_id_;
578	                next.client_req_seq = 0U;
579	                next.event_id = 0U;
580	                next.reboot_verified = false;
581	                next.error.clear();
582	            } else {
583	                next.client_req_seq = item.req_seq;
584	                if (rc != -5 || !ota_status_.active) {
585	                    tracked_task_id_.clear();
586	                    tracked_req_seq_ = 0U;
587	                    pending_reboot_verify_ = false;
588	                    next.active = false;
589	                    next.reboot_verified = false;
590	                    if (item.request.operation == 0U) {
591	                        // 重扫请求被拒或断连时立即作废旧 READY 状态与包摘要，严禁残留旧校验结果。
592	                        next.phase = "FAILED";
593	                        next.mc = AisocOtaNodeInfo{};
594	                        next.th = AisocOtaNodeInfo{};
595	                    }
596	                }
597	                if (rc == -5) {
598	                    next.error = "BACKEND_BUSY";
599	                } else if (conn == nullptr || rc == -100 || rc == AISOC_DBUS_ERR_DISCONNECTED || rc == -1) {
600	                    next.phase = "FAILED";
601	                    next.error = "RPC_DISCONNECTED";
602	                } else {
603	                    next.phase = "FAILED";
604	                    next.error = "OTA_COMMAND_REJECTED";
605	                }
606	            }
607	        }
608	        emit_ota_status(next);
609	    }
610	}
611	
612	void AisocConnection::poll_ota_dds() {
613	    auto* sub = ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
614	    if (sub == nullptr) return;
615	    aisoc_ota_status_t sample = {};
616	    for (uint32_t i = 0U; i < 32U; ++i) {
617	        if (aisoc_dds_take_ota_status(sub, &sample) != AISOC_DDS_OK) break;
618	        AisocOtaStatus parsed;
619	        if (!parse_ota_status_json(sample.json, &parsed)) continue;
620	        bool accept = false;
621	        {
622	            std::lock_guard<std::mutex> lock(mutex_);
623	            const bool task_ok = tracked_task_id_.empty() || parsed.task_id == tracked_task_id_;
624	            const bool mono_ok = (parsed.task_id != ota_status_.task_id) ||
625	                                 (parsed.event_id > ota_status_.event_id);
626	            if (task_ok && mono_ok) {
627	                accept = true;
628	                // 仅当 DDS 快照精确命中本客户端受理的新 task_id 时才打上 tracked_req_seq_。
629	                parsed.client_req_seq = (!tracked_task_id_.empty() && parsed.task_id == tracked_task_id_)
630	                                            ? tracked_req_seq_
631	                                            : 0U;
632	                // 收到真实 DDS 新快照时清零历史 RPC 负码，防止旧错误码污染当前任务状态。
633	                parsed.last_rpc_code = 0;
634	                parsed.reboot_verified = false;
635	                pending_reboot_verify_ = (parsed.phase == "SUCCEEDED");
636	            }
637	        }
638	        if (accept) emit_ota_status(parsed);
639	    }
640	}
