662	void AisocConnection::poll_once() {
663	    AisocSnapshot next;
664	    {
665	        std::lock_guard<std::mutex> lock(mutex_);
666	        next.ap = snapshot_.ap;
667	        next.estop_latched = snapshot_.estop_latched;
668	        next.estop_confirmed = snapshot_.estop_confirmed;
669	        next.last_estop_outcome = snapshot_.last_estop_outcome;
670	        next.last_estop_detail = snapshot_.last_estop_detail;
671	    }
672	    auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
673	    if (conn == nullptr) {
674	        next.estop_latched = false;
675	        next.estop_confirmed = false;
676	        next.device_state = "OFFLINE";
677	        next.system_status = "OFFLINE";
678	        publish_if_changed(next, false);
679	        return;
680	    }
681	    std::string ver_json;
682	    const aisoc_dbus_status_t ver_st = call_dm_string(conn, "GetVersionInfo", config_.rpc_timeout_ms, &ver_json);
683	    if (ver_st != AISOC_DBUS_OK || !parse_dm_version_json(ver_json, &next.mc, &next.th)) {
684	        if (ver_st == AISOC_DBUS_ERR_DISCONNECTED) close_dbus(&dbus_handle_);
685	        next.dm_connected = false;
686	        next.estop_latched = false;
687	        next.estop_confirmed = false;
688	        next.device_state = "OFFLINE";
689	        next.system_status = "OFFLINE";
690	        publish_if_changed(next, false);
691	        return;
692	    }
693	    next.dm_connected = true;
694	    verify_pending_ota_reboot(next.mc, next.th);
695	    std::string snap_json, state_json;
696	    if (call_dm_string(conn, "GetSnapshot", config_.rpc_timeout_ms, &snap_json) == AISOC_DBUS_OK) {
697	        parse_dm_snapshot_json(snap_json, &next);
698	    }
699	    if (call_dm_string(conn, "GetDeviceState", config_.rpc_timeout_ms, &state_json) == AISOC_DBUS_OK) {
700	        std::string state_str;
701	        if (detail::json_extract_string(state_json, "state", &state_str)) next.device_state = state_str;
702	        bool s_latched = false, s_confirmed = false;
703	        if (detail::json_extract_bool(state_json, "estop_latched", &s_latched)) next.estop_latched = s_latched;
704	        if (detail::json_extract_bool(state_json, "estop_confirmed", &s_confirmed)) {
