 49	/** @brief 解析单个 MCU 节点对象 JSON 到 McuNodeInfo。 */
 50	bool parse_single_mcu(const std::string& node_json, McuNodeInfo* out_info) {
 51	    if (out_info == nullptr || !detail::json_is_valid_object(node_json)) return false;
 52	    McuNodeInfo info;
 53	    uint64_t boot_u64 = 0U, cap_u64 = 0U;
 54	    detail::json_extract_bool(node_json, "valid", &info.valid);
 55	    detail::json_extract_string(node_json, "status", &info.status);
 56	    detail::json_extract_string(node_json, "proto_version", &info.proto_version);
 57	    detail::json_extract_string(node_json, "firmware_version", &info.firmware_version);
 58	    if (detail::json_extract_u64(node_json, "boot_id", &boot_u64)) info.boot_id = static_cast<uint32_t>(boot_u64);
 59	    detail::json_extract_string(node_json, "git_commit", &info.git_commit);
 60	    if (detail::json_extract_u64(node_json, "capability_flags", &cap_u64)) {
 61	        info.capability_flags = static_cast<uint32_t>(cap_u64);
 62	    }
 63	    detail::json_extract_u64(node_json, "last_update_ns", &info.last_update_ns);
 64	    info.is_boot_mode = (info.capability_flags & MINIMC_CAP_FLAG_BOOT_MODE) != 0U;
 65	    info.online = info.valid && (info.status == "ONLINE");
 66	    if (info.is_boot_mode && info.online) info.status = "BOOT";
 67	    *out_info = info;
 68	    return true;
 69	}
