 90	/** @brief 确保句柄中的 D-Bus 连接处于已连接状态，断线时自动重建。 */
 91	aisoc_dbus_conn_t* ensure_dbus(void** handle, const std::string& custom_addr) {
 92	    if (handle == nullptr) return nullptr;
 93	    auto* conn = static_cast<aisoc_dbus_conn_t*>(*handle);
 94	    if (conn != nullptr) {
 95	        bool connected = false;
 96	        if (aisoc_dbus_is_connected(conn, &connected) == AISOC_DBUS_OK && connected) return conn;
 97	        aisoc_dbus_conn_close(conn);
 98	        delete conn;
 99	        *handle = nullptr;
100	    }
101	    auto* fresh = new aisoc_dbus_conn_t();
102	    const char* env_addr = std::getenv("DBUS_SESSION_BUS_ADDRESS");
103	    const char* use_addr = !custom_addr.empty() ? custom_addr.c_str() : env_addr;
104	    const aisoc_dbus_conn_config_t cfg = {
105	        use_addr != nullptr ? AISOC_DBUS_BUS_CUSTOM : AISOC_DBUS_BUS_SESSION, use_addr, false};
106	    if (aisoc_dbus_conn_init(&cfg, fresh) != AISOC_DBUS_OK) {
107	        delete fresh;
108	        return nullptr;
109	    }
110	    *handle = fresh;
111	    return fresh;
112	}
