156	/** @brief 调用返回单个 JSON 字符串的 DeviceInterface 只读方法。 */
157	aisoc_dbus_status_t call_dm_string(aisoc_dbus_conn_t* conn, const char* method, int32_t timeout_ms,
158	                                   std::string* out_json) {
159	    if (conn == nullptr || method == nullptr || out_json == nullptr) return AISOC_DBUS_ERR_NULL_PTR;
160	    const aisoc_dbus_method_call_t call = {
161	        AISOC_DBUS_BUS_NAME_DEVICE, AISOC_DBUS_PATH_DEVICE, AISOC_DBUS_IFACE_DEVICE, method};
162	    aisoc_dbus_msg_t req = {}, reply = {};
163	    if (aisoc_dbus_msg_init_call(&call, &req) != AISOC_DBUS_OK) return AISOC_DBUS_ERR_INTERNAL;
164	    const aisoc_dbus_call_opts_t opts = {timeout_ms, true};
165	    const aisoc_dbus_status_t st = aisoc_dbus_call_method(conn, &req, &opts, &reply);
166	    aisoc_dbus_msg_unref(&req);
167	    if (st != AISOC_DBUS_OK) return st;
168	    aisoc_dbus_iter_t iter = {};
169	    aisoc_dbus_iter_init(&reply, &iter);
170	    const char* raw = nullptr;
171	    const aisoc_dbus_status_t r_st = aisoc_dbus_iter_get_string(&iter, &raw);
172	    if (r_st == AISOC_DBUS_OK && raw != nullptr) *out_json = raw;
173	    aisoc_dbus_msg_unref(&reply);
174	    return (r_st == AISOC_DBUS_OK && raw != nullptr) ? AISOC_DBUS_OK : AISOC_DBUS_ERR_TYPE_MISMATCH;
175	}
