177	/** @brief 只读调用 ForwardInterface.QueryVersion，用于在维护恢复期探测 MC Boot/App 身份。 */
178	bool query_forward_version(aisoc_dbus_conn_t* conn, uint8_t target_node, int32_t timeout_ms,
179	                           McuNodeInfo* out_info) {
180	    if (conn == nullptr || out_info == nullptr) return false;
181	    const aisoc_dbus_method_call_t call = {
182	        AISOC_DBUS_BUS_NAME_FORWARD, AISOC_DBUS_PATH_FORWARD, AISOC_DBUS_IFACE_FORWARD, "QueryVersion"};
183	    aisoc_dbus_msg_t req = {}, reply = {};
184	    if (aisoc_dbus_msg_init_call(&call, &req) != AISOC_DBUS_OK) return false;
185	    aisoc_dbus_msg_append_byte(&req, target_node);
186	    aisoc_dbus_msg_append_uint32(&req, static_cast<uint32_t>(timeout_ms));
187	    const aisoc_dbus_call_opts_t opts = {timeout_ms + 200, true};
188	    const aisoc_dbus_status_t st = aisoc_dbus_call_method(conn, &req, &opts, &reply);
189	    aisoc_dbus_msg_unref(&req);
190	    if (st != AISOC_DBUS_OK) return false;
191	    int32_t err = -1;
192	    uint8_t pmaj = 0, pmin = 0, fmaj = 0, fmin = 0;
193	    uint32_t boot_id = 0, commit = 0, flags = 0;
194	    aisoc_dbus_iter_t it = {};
195	    aisoc_dbus_iter_init(&reply, &it);
196	    const bool ok = aisoc_dbus_iter_get_int32(&it, &err) == AISOC_DBUS_OK && err == 0 &&
197	                    aisoc_dbus_iter_get_byte(&it, &pmaj) == AISOC_DBUS_OK &&
198	                    aisoc_dbus_iter_get_byte(&it, &pmin) == AISOC_DBUS_OK &&
199	                    aisoc_dbus_iter_get_byte(&it, &fmaj) == AISOC_DBUS_OK &&
200	                    aisoc_dbus_iter_get_byte(&it, &fmin) == AISOC_DBUS_OK &&
201	                    aisoc_dbus_iter_get_uint32(&it, &boot_id) == AISOC_DBUS_OK &&
202	                    aisoc_dbus_iter_get_uint32(&it, &commit) == AISOC_DBUS_OK &&
203	                    aisoc_dbus_iter_get_uint32(&it, &flags) == AISOC_DBUS_OK;
204	    aisoc_dbus_msg_unref(&reply);
205	    if (!ok) return false;
206	    char buf[32] = {};
207	    out_info->valid = true;
208	    out_info->online = true;
209	    out_info->boot_id = boot_id;
210	    out_info->capability_flags = flags;
211	    out_info->is_boot_mode = (flags & MINIMC_CAP_FLAG_BOOT_MODE) != 0U;
212	    out_info->status = out_info->is_boot_mode ? "BOOT" : "ONLINE";
213	    std::snprintf(buf, sizeof(buf), "%u.%u", pmaj, pmin);
214	    out_info->proto_version = buf;
215	    std::snprintf(buf, sizeof(buf), "%u.%u", fmaj, fmin);
216	    out_info->firmware_version = buf;
217	    std::snprintf(buf, sizeof(buf), "0x%08X", commit);
218	    out_info->git_commit = buf;
219	    return true;
220	}
