222	/** @brief 调用 ForwardInterface.OtaCommand 发起固定目录扫描或升级。 */
223	int32_t execute_fwd_ota_command(aisoc_dbus_conn_t* conn, const AisocOtaRequest& req_data,
224	                                int32_t timeout_ms, uint64_t* out_task_id) {
225	    if (conn == nullptr || out_task_id == nullptr) return -100;
226	    const aisoc_dbus_method_call_t call = {
227	        AISOC_DBUS_BUS_NAME_FORWARD, AISOC_DBUS_PATH_FORWARD, AISOC_DBUS_IFACE_FORWARD, "OtaCommand"};
228	    aisoc_dbus_msg_t req = {}, reply = {};
229	    if (aisoc_dbus_msg_init_call(&call, &req) != AISOC_DBUS_OK) return -100;
230	    aisoc_dbus_msg_append_byte(&req, req_data.operation);
231	    aisoc_dbus_msg_append_byte(&req, req_data.target_mask);
232	    aisoc_dbus_msg_append_bool(&req, req_data.confirmed_safe);
233	    aisoc_dbus_msg_append_bool(&req, req_data.allow_reflash);
234	    aisoc_dbus_msg_append_string(&req, req_data.mc_sha256.c_str());
235	    aisoc_dbus_msg_append_string(&req, req_data.th_sha256.c_str());
236	    const aisoc_dbus_call_opts_t opts = {timeout_ms > 1000 ? timeout_ms : 1000, true};
237	    const aisoc_dbus_status_t st = aisoc_dbus_call_method(conn, &req, &opts, &reply);
238	    aisoc_dbus_msg_unref(&req);
239	    if (st != AISOC_DBUS_OK) {
240	        if (st == AISOC_DBUS_ERR_DISCONNECTED || st == AISOC_DBUS_ERR_INTERNAL || st == AISOC_DBUS_ERR_NO_REPLY) {
241	            return -100;
242	        }
243	        return static_cast<int32_t>(st);
244	    }
245	    aisoc_dbus_iter_t it = {};
246	    aisoc_dbus_iter_init(&reply, &it);
247	    int32_t err_code = -1;
248	    uint64_t task_id = 0U;
249	    const bool ok = aisoc_dbus_iter_get_int32(&it, &err_code) == AISOC_DBUS_OK &&
250	                    aisoc_dbus_iter_get_uint64(&it, &task_id) == AISOC_DBUS_OK;
251	    aisoc_dbus_msg_unref(&reply);
252	    if (!ok) return -1;
253	    *out_task_id = task_id;
254	    return err_code;
255	}
