416	void AisocConnection::stop() {
417	    std::thread to_join;
418	    {
419	        std::lock_guard<std::mutex> lock(mutex_);
420	        if (!running_ && !worker_.joinable()) {
421	            close_dds_ota(&dds_part_, &dds_ota_sub_);
422	            close_dbus(&dbus_handle_);
423	            return;
424	        }
425	        stop_requested_ = true;
426	        cv_.notify_all();
427	        to_join = std::move(worker_);
428	    }
429	    if (to_join.joinable()) to_join.join();
430	    std::lock_guard<std::mutex> lock(mutex_);
431	    running_ = false;
432	    close_dds_ota(&dds_part_, &dds_ota_sub_);
433	    close_dbus(&dbus_handle_);
434	}
