612	void AisocConnection::poll_ota_dds() {
613	    auto* sub = ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
614	    if (sub == nullptr) return;
615	    aisoc_ota_status_t sample = {};
616	    for (uint32_t i = 0U; i < 32U; ++i) {
617	        if (aisoc_dds_take_ota_status(sub, &sample) != AISOC_DDS_OK) break;
618	        AisocOtaStatus parsed;
619	        if (!parse_ota_status_json(sample.json, &parsed)) continue;
620	        bool accept = false;
621	        {
622	            std::lock_guard<std::mutex> lock(mutex_);
623	            const bool task_ok = tracked_task_id_.empty() || parsed.task_id == tracked_task_id_;
624	            const bool mono_ok = (parsed.task_id != ota_status_.task_id) ||
625	                                 (parsed.event_id > ota_status_.event_id);
626	            if (task_ok && mono_ok) {
627	                accept = true;
628	                // 仅当 DDS 快照精确命中本客户端受理的新 task_id 时才打上 tracked_req_seq_。
629	                parsed.client_req_seq = (!tracked_task_id_.empty() && parsed.task_id == tracked_task_id_)
630	                                            ? tracked_req_seq_
631	                                            : 0U;
632	                // 收到真实 DDS 新快照时清零历史 RPC 负码，防止旧错误码污染当前任务状态。
633	                parsed.last_rpc_code = 0;
634	                parsed.reboot_verified = false;
635	                pending_reboot_verify_ = (parsed.phase == "SUCCEEDED");
636	            }
637	        }
638	        if (accept) emit_ota_status(parsed);
639	    }
640	}
