642	void AisocConnection::verify_pending_ota_reboot(const McuNodeInfo& dm_mc, const McuNodeInfo& dm_th) {
643	    AisocOtaStatus verified;
644	    bool newly_verified = false;
645	    {
646	        std::lock_guard<std::mutex> lock(mutex_);
647	        if (!pending_reboot_verify_ || ota_status_.phase != "SUCCEEDED") return;
648	        const uint32_t mask = ota_status_.target_mask;
649	        if (mask == 0U) return;
650	        const bool mc_ok = ((mask & 1U) == 0U) || node_reboot_verified(dm_mc, ota_status_.mc.pre_boot_id);
651	        const bool th_ok = ((mask & 2U) == 0U) || node_reboot_verified(dm_th, ota_status_.th.pre_boot_id);
652	        if (mc_ok && th_ok) {
653	            pending_reboot_verify_ = false;
654	            ota_status_.reboot_verified = true;
655	            verified = ota_status_;
656	            newly_verified = true;
657	        }
658	    }
659	    if (newly_verified) emit_ota_status(verified);
660	}
