719	    {
720	        std::lock_guard<std::mutex> lock(mutex_);
721	        if (!force_emit && snapshot_equal(snapshot_, next_snap)) return;
722	        snapshot_ = next_snap;
723	        cb = snapshot_cb_;
724	        ota_cb = ota_cb_;
725	        ota_snap = ota_status_;
