756	AisocOtaGateVerdict check_ota_scan_gate(bool has_conn, const AisocOtaStatus& st) {
757	    if (!has_conn) return AisocOtaGateVerdict::DISCONNECTED;
758	    // 仅拦截在途活跃任务；MC 待恢复模式 (!st.active && st.maintenance) 必须允许扫描恢复包。
759	    if (st.active) return AisocOtaGateVerdict::BACKEND_BUSY;
760	    return AisocOtaGateVerdict::ALLOW;
761	}
762	
763	AisocOtaGateVerdict check_ota_upgrade_gate(uint8_t mask, bool confirmed_safe,
764	                                           const AisocOtaStatus& st, const AisocSnapshot& snap) {
765	    if (mask == 0U || !confirmed_safe) return AisocOtaGateVerdict::MISSING_SELECTION;
766	    if (st.active) return AisocOtaGateVerdict::BACKEND_BUSY;
767	    const bool mc_recovery = (!st.active) && (st.maintenance || snap.mc.is_boot_mode ||
768	                                              st.error == "RESTORE_MC_BEFORE_TH");
769	    if (mc_recovery && mask != 1U) return AisocOtaGateVerdict::MC_RECOVERY_ONLY;
770	    const bool mc_ready = ((mask & 1U) == 0U) || is_ota_node_pkg_ready(st.mc);
771	    const bool th_ready = ((mask & 2U) == 0U) || is_ota_node_pkg_ready(st.th);
772	    if (!mc_ready || !th_ready) return AisocOtaGateVerdict::PACKAGE_NOT_READY;
773	    if (!snap.dm_connected) return AisocOtaGateVerdict::DISCONNECTED;
774	    // MC 待恢复单选升级允许通过串口直接刷回 App，不因 DM 暂报 MC 离线阻断恢复。
775	    const bool mc_online = ((mask & 1U) == 0U) || snap.mc.online || mc_recovery;
776	    const bool th_online = ((mask & 2U) == 0U) || snap.th.online;
777	    if (!mc_online || !th_online) return AisocOtaGateVerdict::NODE_OFFLINE;
778	    return AisocOtaGateVerdict::ALLOW;
779	}
