781	AisocScanFeedback evaluate_ota_scan_feedback(uint64_t pending_scan_seq, const AisocOtaStatus& st) {
782	    if (pending_scan_seq == 0U || st.client_req_seq != pending_scan_seq) {
783	        return AisocScanFeedback::NONE;
784	    }
785	    if (st.last_rpc_code < 0) {
786	        return (st.error == "RPC_DISCONNECTED") ? AisocScanFeedback::ERROR : AisocScanFeedback::WARNING;
787	    }
788	    const bool scan_done = (!st.active) && (st.phase == "READY" || st.phase == "FAILED");
789	    if (!scan_done) return AisocScanFeedback::NONE;
790	    return (st.phase == "READY") ? AisocScanFeedback::SUCCESS : AisocScanFeedback::WARNING;
791	}
