793	AisocOtaLockState evaluate_ota_lock_state(const AisocOtaStatus& st, const AisocSnapshot& snap) {
794	    // 忙锁仅取决于实时在途状态，不读取历史急停结果 last_estop_outcome。
795	    const bool busy = st.active || (st.last_rpc_code == -5) || snap.maintenance_locked;
796	    if (busy) return AisocOtaLockState::BUSY;
797	    if (snap.estop_confirmed) return AisocOtaLockState::ESTOP_CONFIRMED;
798	    if (snap.estop_latched) return AisocOtaLockState::ESTOP_LATCHED_UNCONFIRMED;
799	    if (!snap.dm_connected) return AisocOtaLockState::DISCONNECTED;
800	    if (st.maintenance || snap.mc.is_boot_mode) return AisocOtaLockState::MC_RECOVERY;
801	    if (!snap.mc.online || !snap.th.online) return AisocOtaLockState::NODE_OFFLINE;
802	    return AisocOtaLockState::READY;
803	}
