   488	void AisocConnection::worker_loop() {
   489	    while (true) {
   490	        process_pending_estops();
   491	        process_pending_ota();
   492	        poll_ota_dds();
   493	        bool do_refresh = false;
   494	        {
   495	            std::lock_guard<std::mutex> lock(mutex_);
   496	            if (stop_requested_) break;
   497	            do_refresh = refresh_requested_;
   498	            refresh_requested_ = false;
   499	        }
   500	        poll_once();
   501	        poll_ota_dds();
   502	        if (do_refresh) process_pending_estops();
   503	        std::unique_lock<std::mutex> lock(mutex_);
   504	        if (stop_requested_) break;
   505	        uint32_t wait_ms = config_.poll_interval_ms > 0U ? config_.poll_interval_ms : 1000U;
   506	        if ((ota_status_.active || pending_reboot_verify_) && wait_ms > 80U) wait_ms = 80U;
   507	        cv_.wait_for(lock, std::chrono::milliseconds(wait_ms), [this]() {
   508	            return stop_requested_ || refresh_requested_ || !estop_queue_.empty() || !ota_queue_.empty();
   509	        });
   510	        if (stop_requested_) break;
   511	    }
   512	}
   513	
   514	void AisocConnection::process_pending_estops() {
   515	    while (true) {
   516	        bool engage = true;
   517	        EstopCallback cb;
   518	        {
   519	            std::lock_guard<std::mutex> lock(mutex_);
   520	            if (stop_requested_ || estop_queue_.empty()) return;
   521	            engage = estop_queue_.front();
   522	            estop_queue_.erase(estop_queue_.begin());
   523	            cb = estop_cb_;
   524	        }
   525	        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
   526	        const AisocEstopResult res = execute_dm_estop(conn, engage, config_.rpc_timeout_ms);
   527	        if (res.outcome == AisocEstopOutcome::DISCONNECTED) close_dbus(&dbus_handle_);
   528	        AisocSnapshot updated;
   529	        AisocOtaStatus ota_snap;
   530	        OtaStatusCallback ota_cb;
   531	        {
   532	            std::lock_guard<std::mutex> lock(mutex_);
   533	            if (res.outcome == AisocEstopOutcome::CONFIRMED) {
   534	                snapshot_.estop_latched = engage;
   535	                snapshot_.estop_confirmed = engage;
   536	            } else if (res.outcome == AisocEstopOutcome::DISCONNECTED) {
   537	                snapshot_.estop_latched = false;
   538	                snapshot_.estop_confirmed = false;
   539	            } else if (engage && res.outcome == AisocEstopOutcome::FAILED) {
   540	                snapshot_.estop_confirmed = false;
   541	                refresh_requested_ = true;
   542	            }
   543	            snapshot_.last_estop_outcome = res.outcome;
   544	            snapshot_.last_estop_detail = res.detail;
   545	            updated = snapshot_;
   546	            ota_snap = ota_status_;
   547	            ota_cb = ota_cb_;
   548	        }
   549	        publish_if_changed(updated, true);
   550	        if (ota_cb) ota_cb(ota_snap);
   551	        if (cb) cb(res);
   552	    }
   553	}
