   555	void AisocConnection::process_pending_ota() {
   556	    while (true) {
   557	        QueuedOtaRequest item;
   558	        {
   559	            std::lock_guard<std::mutex> lock(mutex_);
   560	            if (stop_requested_ || ota_queue_.empty()) return;
   561	            item = ota_queue_.front();
   562	            ota_queue_.erase(ota_queue_.begin());
   563	        }
   564	        ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
   565	        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
   566	        uint64_t task_id = 0U;
   567	        const int32_t rc = execute_fwd_ota_command(conn, item.request, config_.rpc_timeout_ms, &task_id);
   568	        AisocOtaStatus next;
   569	        {
   570	            std::lock_guard<std::mutex> lock(mutex_);
   571	            next = ota_status_;
   572	            next.last_rpc_code = rc;
   573	            if (rc == 0) {
   574	                tracked_task_id_ = std::to_string(task_id);
   575	                tracked_req_seq_ = item.req_seq;
   576	                pending_reboot_verify_ = false;
   577	                next.task_id = tracked_task_id_;
   578	                next.client_req_seq = 0U;
   579	                next.event_id = 0U;
   580	                next.reboot_verified = false;
   581	                next.error.clear();
   582	            } else {
   583	                next.client_req_seq = item.req_seq;
   584	                if (rc != -5 || !ota_status_.active) {
   585	                    tracked_task_id_.clear();
   586	                    tracked_req_seq_ = 0U;
   587	                    pending_reboot_verify_ = false;
   588	                    next.active = false;
   589	                    next.reboot_verified = false;
   590	                    if (item.request.operation == 0U) {
   591	                        // 重扫请求被拒或断连时立即作废旧 READY 状态与包摘要，严禁残留旧校验结果。
   592	                        next.phase = "FAILED";
   593	                        next.mc = AisocOtaNodeInfo{};
   594	                        next.th = AisocOtaNodeInfo{};
   595	                    }
   596	                }
   597	                if (rc == -5) {
   598	                    next.error = "BACKEND_BUSY";
   599	                } else if (conn == nullptr || rc == -100 || rc == AISOC_DBUS_ERR_DISCONNECTED || rc == -1) {
   600	                    next.phase = "FAILED";
   601	                    next.error = "RPC_DISCONNECTED";
   602	                } else {
   603	                    next.phase = "FAILED";
   604	                    next.error = "OTA_COMMAND_REJECTED";
   605	                }
   606	            }
   607	        }
   608	        emit_ota_status(next);
   609	    }
   610	}
   248	        state->estop_confirmed = true;
   249	        state->generation_id += 1U;
   250	        state->snapshot.generation_id = state->generation_id;
   251	    }
   252	    pthread_mutex_unlock(&state->state_mutex);
   253	}
