   255	/**
   256	 * @brief 处理 D-Bus EmergencyStop 请求：触发或清除急停锁定并转发至 ForwardService
   257	 * @param req D-Bus 请求消息指针
   258	 * @param reply D-Bus 响应消息指针
   259	 * @param user_data 用户上下文指针（指向 device_manager_state_t）
   260	 * @return aisoc_dbus_status_t 成功返回 AISOC_DBUS_OK
   261	 */
   262	static aisoc_dbus_status_t handle_emergency_stop(
   263	    const aisoc_dbus_msg_t* req,
   264	    aisoc_dbus_msg_t* reply,
   265	    void* user_data
   266	) {
   267	    if (req == nullptr || reply == nullptr || user_data == nullptr) return AISOC_DBUS_ERR_NULL_PTR;
   268	    device_manager_state_t* state = (device_manager_state_t*)user_data;
   269	    aisoc_dbus_iter_t iter;
   270	    aisoc_dbus_iter_init(req, &iter);
   271	    uint8_t reason_code = 0U;
   272	    if (aisoc_dbus_iter_get_byte(&iter, &reason_code) != AISOC_DBUS_OK || reason_code > 1U) {
   273	        aisoc_dbus_msg_append_int32(reply, AISOC_DEV_ERR_INVALID_ARG);
   274	        return AISOC_DBUS_OK;
   275	    }
   276	    pthread_mutex_lock(&state->state_mutex);
   277	    const bool in_maint = state->is_maintenance || state->ota_recovery_pending;
   278	    const bool prev_latched = state->estop_latched;
   279	    pthread_mutex_unlock(&state->state_mutex);
   280	    // 固件维护锁定期间拒绝并发急停（返回 -5 BUSY），避免污染维护态并在升级完成后残留假急停锁。
   281	    if (in_maint) {
   282	        aisoc_dbus_msg_append_int32(reply, AISOC_DEV_ERR_BUSY);
   283	        return AISOC_DBUS_OK;
   284	    }
   285	    const auto policy = reason_code == 0U ? dev_control_policy::CLEAR : dev_control_policy::STOP;
   286	    const int32_t admission = control_permission(state, 3U, policy);
   287	    if (admission != 0) {
   288	        aisoc_dbus_msg_append_int32(reply, admission);
   289	        return AISOC_DBUS_OK;
   290	    }
   291	    if (reason_code == 1U) latch_emergency_stop(state);
   292	
   293	    aisoc_dbus_method_call_t call = {
   294	        AISOC_DBUS_BUS_NAME_FORWARD, AISOC_DBUS_PATH_FORWARD, AISOC_DBUS_IFACE_FORWARD, "EmergencyStop"
   295	    };
   296	    aisoc_dbus_msg_t fwd_req, fwd_reply;
   297	    aisoc_dbus_msg_init_call(&call, &fwd_req);
   298	    aisoc_dbus_msg_append_byte(&fwd_req, reason_code);
   299	    aisoc_dbus_call_opts_t fwd_opts = { 600, true };
   300	    const aisoc_dbus_status_t fwd_st = aisoc_dbus_call_method(&state->dbus_conn, &fwd_req, &fwd_opts, &fwd_reply);
   301	    aisoc_dbus_msg_unref(&fwd_req);
   302	    int32_t fwd_err = (int32_t)fwd_st;
   303	    if (fwd_st == AISOC_DBUS_OK) {
   304	        aisoc_dbus_iter_t r_iter;
   305	        aisoc_dbus_iter_init(&fwd_reply, &r_iter);
   306	        if (aisoc_dbus_iter_get_int32(&r_iter, &fwd_err) != AISOC_DBUS_OK) fwd_err = AISOC_DEV_ERR_FAULT;
   307	        aisoc_dbus_msg_unref(&fwd_reply);
   308	    }
   309	    if (reason_code == 1U && fwd_err == 0) confirm_emergency_stop(state);
   310	    else if (reason_code == 1U && fwd_err == AISOC_DEV_ERR_BUSY && !prev_latched) clear_emergency_stop_state(state);
   311	    if (reason_code == 0U && fwd_err == 0) clear_emergency_stop_state(state);
   312	    aisoc_dbus_msg_append_int32(reply, fwd_err);
   313	    return AISOC_DBUS_OK;
   314	}
