aisoc_fwd_status_t forward_service_set_temperature(forward_service_state_t* state,
    uint8_t target_mask, const minimc_set_temp_req_t* request, minimc_temp_wire_payload_t* output) {
    if (state == nullptr || request == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (output == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (!valid_mask(target_mask)) return AISOC_FWD_ERR_INVALID_ARG;
    const uint8_t mask = target_mask == 0U ? 3U : target_mask;
    temperature_result results[2];
    size_t count = 0U;
    auto status = AISOC_FWD_OK;
    pthread_mutex_lock(&state->uart_mutex);
    for (uint8_t index = 0U; index < 2U; ++index) {
        if ((mask & (1U << index)) == 0U) continue;
        if (count > 0U) usleep(45000);
        status = set_temperature_node(state, static_cast<uint8_t>(2U + index), request, &results[count]);
        if (status != AISOC_FWD_OK) break;
        count += 1U;
    }
    pthread_mutex_unlock(&state->uart_mutex);
    // 保持未配置 writer 的内部诊断兼容；生产 writer 失败必须向上传播，不能重发硬件命令。
    auto publish_status = AISOC_FWD_OK;
    for (size_t index = 0U; index < count; ++index) {
        if (state->dds_pub_raw_temp == nullptr) break;
        if (aisoc_dds_publish_raw_temp(state->dds_pub_raw_temp, &results[index].sample) != AISOC_DDS_OK)
            publish_status = AISOC_FWD_ERR_DDS_PUBLISH;
    }
    if (status != AISOC_FWD_OK) return status;
    if (publish_status != AISOC_FWD_OK) return publish_status;
    *output = results[count - 1U].wire;
    return AISOC_FWD_OK;
}

/** @file device_manager_admission.cpp
 * @brief 控制发送前核验准入；温度和身份分别计时，Boot身份不能作为App就绪。
 */
#include "device_manager_admission.h"
#include "device_manager_state.h"
#include <ctime>
/** @brief 返回单调纳秒时间；无输入，无硬件或状态副作用。 */
static uint64_t monotonic_ns() {
    timespec timestamp = {};
    clock_gettime(CLOCK_MONOTONIC, &timestamp);
    return static_cast<uint64_t>(timestamp.tv_sec) * 1000000000ULL + timestamp.tv_nsec;
}
/** @brief timestamp为最后真实应答、now为当前时间；非零、非未来且未达1.5s才返回真。 */
static bool fresh(uint64_t timestamp, uint64_t now) {
    return timestamp != 0U && timestamp <= now && now - timestamp < AISOC_DEV_VER_ONLINE_TIMEOUT_NS;
}
/** @brief state/node/now为锁内状态、逻辑节点1或2及时间；身份与通道质量都可用才返回真。 */
static bool node_ready(const device_manager_state_t* state, uint8_t node, uint64_t now) {
    aisoc_dev_mcu_version_t version = {};
    const char* name = node == 1U ? "MC" : "TH";
    if (dev_state_get_mcu_version(state, name, &version) != AISOC_DEV_OK) return false;
    const bool identified = version.is_valid && version.status == DEV_VER_STATUS_ONLINE;
    if (!identified || !fresh(version.last_update_ns, now)) return false;
    if (version.proto_major != 2U || version.boot_id == 0U) return false;
    if ((version.capability_flags & MINIMC_CAP_FLAG_BOOT_MODE) != 0U) return false;
    const auto& snapshot = state->snapshot;
    const uint32_t sensor = node == 1U ? snapshot.bed_sensor_status : snapshot.tool_sensor_status;
    const uint32_t quality = node == 1U ? snapshot.bed_quality : snapshot.tool_quality;
    const uint64_t received = node == 1U ? state->last_bed_rx_ns : state->last_tool_rx_ns;
    return sensor == AISOC_SENSOR_OK && quality == AISOC_QUALITY_FRESH && fresh(received, now);
}
aisoc_dev_status_t dev_state_control_admission(const device_manager_state_t* state,
    uint8_t mask, dev_control_policy policy) {
    if (state == nullptr) return AISOC_DEV_ERR_NULL_PTR;
    if (mask == 0U || mask > 3U) return AISOC_DEV_ERR_INVALID_ARG;
    if (policy == dev_control_policy::QUERY || policy == dev_control_policy::STOP) return AISOC_DEV_OK;
    if (state->is_maintenance || state->ota_recovery_pending) return AISOC_DEV_ERR_BUSY;
    const bool fault = state->is_fault || state->estop_latched;
    if (policy == dev_control_policy::ACTUATE && fault) return AISOC_DEV_ERR_FAULT;
    const uint64_t now = monotonic_ns();
    for (uint8_t node = 1U; node <= 2U; ++node) {
        if ((mask & (1U << (node - 1U))) == 0U) continue;
        if (!node_ready(state, node, now)) return AISOC_DEV_ERR_TIMEOUT;
    }
    return AISOC_DEV_OK;
}
