}

/** @brief 将统一并发/急停/连接锁状态枚举映射为经过 CJK 字库覆盖核验的标准提示文案。 */
static const char* format_ota_lock_text(helix::aisoc::AisocOtaLockState state) {
    using helix::aisoc::AisocOtaLockState;
    switch (state) {
        case AisocOtaLockState::BUSY:
            return "状态: 后台已锁定 (BUSY)";
        case AisocOtaLockState::ESTOP_CONFIRMED:
            return "状态: 设备已确认急停";
        case AisocOtaLockState::ESTOP_LATCHED_UNCONFIRMED:
            return "状态: 本地急停已锁存（板卡未全部应答）";
        case AisocOtaLockState::DISCONNECTED:
            return "状态: 本地服务未连接（请检查后台服务后重试）";
        case AisocOtaLockState::MC_RECOVERY:
            return "状态: MC 处于待恢复模式，请取消选择 TH 仅升级 MC";
        case AisocOtaLockState::NODE_OFFLINE:
            return "状态: 节点离线（请检查板卡连接待恢复 ONLINE 后重试）";
        case AisocOtaLockState::READY:
        default:
            return "状态: 就绪";
    }
}

