    63	static void on_control_event(void* context, const fwd_comm_event_t* event) {
    64	    if (context == nullptr || event == nullptr) return;
    65	    auto* completion = static_cast<control_completion*>(context);
    66	    completion->status = fwd_exchange_status(event->status);
    67	    completion->elapsed_ms = event->elapsed_ms;
    68	    completion->reply.sequence_id = event->sequence_id;
    69	    if (event->status != FWD_COMM_OK) return;
    70	    // 通信层已检查 ACK 固定 4B；保留字节非零不能成为有效确认。
    71	    if (event->response_cmd == MINIMC_CMD_ACK) {
    72	        const bool reserved_ok = event->data[2] == 0U && event->data[3] == 0U;
