    74	            completion->status = AISOC_FWD_ERR_INVALID_ARG;
    75	            return;
    76	        }
    77	    }
    78	    auto* frame = &completion->reply.frame;
    79	    frame->rx_cmd = event->response_cmd;
    80	    frame->elapsed_ms = event->elapsed_ms;
    81	    frame->payload_len = event->data_len;
    82	    if (event->data_len > 0U) std::memcpy(frame->payload, event->data, event->data_len);
    83	}
