   207	static void clear_emergency_stop_state(device_manager_state_t* state) {
   208	    if (state == nullptr) return;
   209	    char old_state[32] = {}, new_state[32] = {};
   210	    pthread_mutex_lock(&state->state_mutex);
   211	    std::snprintf(old_state, sizeof(old_state), "%s", state->device_state);
   212	    // 重复/未锁存解除不能用旧的急停前快照覆盖后来产生的其它故障。
   213	    if (state->estop_latched) state->is_fault = state->fault_before_estop;
   214	    state->estop_latched = false;
   215	    state->estop_confirmed = false;
   216	    std::snprintf(state->device_state, sizeof(state->device_state), "%s", state->is_fault ? "FAULT" : "IDLE");
   217	    dev_state_eval_freshness(state, get_host_monotonic_ns());
   218	    state->generation_id += 1U;
   219	    state->snapshot.generation_id = state->generation_id;
   220	    std::snprintf(new_state, sizeof(new_state), "%s", state->device_state);
   221	    pthread_mutex_unlock(&state->state_mutex);
   222	    dev_dbus_emit_state_changed(state, old_state, new_state, "Emergency stop cleared");
   223	}
  * @param  ticks: 当前已累计的非驻留探测毫秒数 (用于无有效 App 时的整秒限流打印)
  */
static void handle_no_disk_timeout(uint32_t ticks) {
  if (is_app_valid(FLASH_APP_ADDR)) {
    printf("Probe timeout. Valid App found at 0x%08X.\r\n", FLASH_APP_ADDR);
    printf("Jumping to application...\r\n");
    jump_to_app(FLASH_APP_ADDR);
  } else {
    /* 未找到有效 App 且无 U 盘时，每隔 1000ms (1 秒) 周期输出提示 */
    if ((ticks % 1000U) == 0U) {
      printf("No valid App at 0x%08X. Waiting for U-disk...\r\n",
             FLASH_APP_ADDR);
    }
  }
}

