/** @brief 验证 S09-03 UNSCANNED 拦截与 MC 待恢复模式 (!active && maintenance) 单板门禁。 */
bool verify_mc_recovery_gate(AisocConnection* conn, aisoc_dds_publisher_t* pub) {
    AisocOtaRequest scan_req;
    scan_req.operation = 0U;
    scan_req.target_mask = 3U;
    conn->request_ota(scan_req);
    if (!wait_until([&]() { return conn->ota_status().task_id == "7006"; })) return false;
    const std::string rec_idle =
        "{\"schema_version\":1,\"policy\":\"integrity-only-hil\",\"task_id\":\"7006\",\"event_id\":1,"
        "\"phase\":\"IDLE\",\"active\":false,\"maintenance\":true,\"target_mask\":1,\"active_node\":2,"
        "\"progress_pct\":0,\"error\":\"RESTORE_MC_BEFORE_TH\","
        "\"mc\":{\"valid\":false,\"scan_state\":\"UNSCANNED\",\"scan_error\":\"\",\"file\":\"fw_mc.bin\",\"size\":0,\"sha256\":\"\"},"
        "\"th\":{\"valid\":false,\"scan_state\":\"UNSCANNED\",\"scan_error\":\"\",\"file\":\"fw_th.bin\",\"size\":0,\"sha256\":\"\"}}";
    publish_ota_sample(pub, rec_idle);
    if (!wait_until([&]() {
        const auto s = conn->ota_status();
        return !s.active && s.maintenance && s.phase == "IDLE" && s.error == "RESTORE_MC_BEFORE_TH";
    })) return false;
    if (check_ota_scan_gate(true, conn->ota_status()) != AisocOtaGateVerdict::ALLOW) return false;
    // S09-03：即便残留旧 valid=true 与 sha256，只要 scan_state != READY 必须判定为未就绪。
    AisocOtaStatus stale_unscanned = conn->ota_status();
    stale_unscanned.maintenance = false;
    stale_unscanned.error.clear();
    stale_unscanned.mc.scan_state = "READY";
    stale_unscanned.mc.valid = true;
    stale_unscanned.mc.sha256 = std::string(64, 'a');
    stale_unscanned.th.scan_state = "UNSCANNED";
    stale_unscanned.th.valid = true;
    stale_unscanned.th.sha256 = std::string(64, 'b');
    AisocSnapshot online_snap;
    online_snap.dm_connected = true;
    online_snap.mc.online = true;
    online_snap.th.online = true;
    if (is_ota_node_pkg_ready(stale_unscanned.th) ||
        check_ota_upgrade_gate(3U, true, stale_unscanned, online_snap) != AisocOtaGateVerdict::PACKAGE_NOT_READY) {
        return false;
    }
    AisocOtaStatus ready_rec = stale_unscanned;
    ready_rec.maintenance = true;
    ready_rec.error = "RESTORE_MC_BEFORE_TH";
    ready_rec.th.scan_state = "READY";
    AisocSnapshot rec_snap;
    rec_snap.dm_connected = true;
    rec_snap.mc.is_boot_mode = true;
    return check_ota_upgrade_gate(3U, true, ready_rec, rec_snap) == AisocOtaGateVerdict::MC_RECOVERY_ONLY &&
           check_ota_upgrade_gate(2U, true, ready_rec, rec_snap) == AisocOtaGateVerdict::MC_RECOVERY_ONLY &&
           check_ota_upgrade_gate(1U, true, ready_rec, rec_snap) == AisocOtaGateVerdict::ALLOW;
}

