static bool valid_hash(const char* text) {
    if (text == nullptr || std::strlen(text) != 64U) return false;
    for (size_t index = 0U; index < 64U; ++index) {
        const bool lower = text[index] >= 'a' && text[index] <= 'f';
        const bool digit = text[index] >= '0' && text[index] <= '9';
        if (!lower && !digit) return false;
    }

